-- Schema created by src/database.js (Node runtime, schema_version 3) with PRAGMA user_version 0.
-- Generated by running new LumenCortexDatabase(dir) and dumping sqlite_master. The node_fts FTS5 virtual
-- table and its shadow tables are omitted: go-sqlite3 is built without the fts5 module.

CREATE TABLE metadata (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
      ) STRICT;

CREATE TABLE repository_state (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
      ) STRICT;

CREATE TABLE graph_nodes (
        id TEXT PRIMARY KEY,
        kind TEXT NOT NULL,
        status TEXT NOT NULL,
        title TEXT NOT NULL,
        body TEXT NOT NULL,
        path TEXT,
        source_kind TEXT,
        updated_at TEXT,
        version INTEGER NOT NULL,
        json TEXT NOT NULL
      ) STRICT;

CREATE INDEX idx_graph_nodes_kind_status
        ON graph_nodes(kind, status);

CREATE INDEX idx_graph_nodes_path
        ON graph_nodes(path);

CREATE TABLE graph_node_storage (
        node_id TEXT PRIMARY KEY,
        tier TEXT NOT NULL CHECK(tier IN ('hot', 'warm', 'cold')),
        last_access_at TEXT,
        last_tier_change_at TEXT NOT NULL,
        archived_at TEXT,
        compacted_at TEXT,
        access_count INTEGER NOT NULL DEFAULT 0,
        FOREIGN KEY(node_id) REFERENCES graph_nodes(id) ON DELETE CASCADE
      ) STRICT;

CREATE INDEX idx_graph_node_storage_tier_access
        ON graph_node_storage(tier, last_access_at);

CREATE INDEX idx_graph_node_storage_archive
        ON graph_node_storage(tier, archived_at);

CREATE TABLE graph_edges (
        id TEXT PRIMARY KEY,
        from_id TEXT NOT NULL,
        to_id TEXT NOT NULL,
        type TEXT NOT NULL,
        weight REAL NOT NULL,
        json TEXT NOT NULL,
        FOREIGN KEY(from_id) REFERENCES graph_nodes(id) ON DELETE CASCADE,
        FOREIGN KEY(to_id) REFERENCES graph_nodes(id) ON DELETE CASCADE
      ) STRICT;

CREATE INDEX idx_graph_edges_from ON graph_edges(from_id);

CREATE INDEX idx_graph_edges_to ON graph_edges(to_id);

CREATE INDEX idx_graph_edges_type ON graph_edges(type);

CREATE TABLE cognitive_commits (
        id TEXT PRIMARY KEY,
        format_version INTEGER NOT NULL,
        message TEXT NOT NULL,
        parents_json TEXT NOT NULL,
        created_at TEXT NOT NULL,
        graph_hash TEXT NOT NULL,
        diff_json TEXT NOT NULL,
        metadata_json TEXT NOT NULL
      ) STRICT;

CREATE INDEX idx_cognitive_commits_created
        ON cognitive_commits(created_at DESC);

CREATE TABLE cognitive_checkpoints (
        commit_id TEXT PRIMARY KEY,
        snapshot_json TEXT NOT NULL,
        created_at TEXT NOT NULL,
        FOREIGN KEY(commit_id) REFERENCES cognitive_commits(id) ON DELETE CASCADE
      ) STRICT;

CREATE TABLE cognitive_refs (
        name TEXT PRIMARY KEY,
        commit_id TEXT NOT NULL,
        FOREIGN KEY(commit_id) REFERENCES cognitive_commits(id)
      ) STRICT;

CREATE TABLE sessions (
        id TEXT PRIMARY KEY,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        status TEXT NOT NULL,
        provider TEXT,
        model TEXT,
        goal TEXT NOT NULL,
        metadata_json TEXT NOT NULL,
        final TEXT,
        usage_json TEXT,
        error_json TEXT
      ) STRICT;

CREATE INDEX idx_sessions_updated
        ON sessions(updated_at DESC);

CREATE TABLE session_messages (
        session_id TEXT NOT NULL,
        seq INTEGER NOT NULL,
        role TEXT NOT NULL,
        json TEXT NOT NULL,
        PRIMARY KEY(session_id, seq),
        FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE
      ) STRICT;

CREATE TABLE agent_steps (
        session_id TEXT NOT NULL,
        step INTEGER NOT NULL,
        json TEXT NOT NULL,
        PRIMARY KEY(session_id, step),
        FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE
      ) STRICT;

CREATE TABLE journal (
        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        at TEXT NOT NULL,
        event TEXT NOT NULL,
        payload_json TEXT NOT NULL
      ) STRICT;

CREATE INDEX idx_journal_event_at
        ON journal(event, at DESC);

CREATE TABLE search_documents (
        node_id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        path TEXT,
        kind TEXT NOT NULL,
        source_kind TEXT,
        content_hash TEXT,
        length INTEGER NOT NULL
      ) STRICT;

CREATE TABLE symbols (
        symbol TEXT NOT NULL,
        node_id TEXT NOT NULL,
        PRIMARY KEY(symbol, node_id),
        FOREIGN KEY(node_id) REFERENCES search_documents(node_id) ON DELETE CASCADE
      ) WITHOUT ROWID;

CREATE INDEX idx_symbols_node ON symbols(node_id);

CREATE TABLE search_dirty_nodes (
        node_id TEXT PRIMARY KEY,
        removed INTEGER NOT NULL DEFAULT 0
      ) STRICT;

CREATE TABLE node_embeddings (
        node_id TEXT NOT NULL,
        model TEXT NOT NULL,
        dimension INTEGER NOT NULL,
        content_hash TEXT NOT NULL,
        vector_json TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        PRIMARY KEY(node_id, model),
        FOREIGN KEY(node_id) REFERENCES graph_nodes(id) ON DELETE CASCADE
      ) STRICT;

CREATE INDEX idx_node_embeddings_model
        ON node_embeddings(model, node_id);

INSERT INTO metadata(key, value) VALUES('schema_version', '3');

